declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('charity');$pdo=db();$charityId=(int)$user['charity_id'];$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$editing=(bool)$id;$errors=[];
$request=['title'=>'','description'=>'','season'=>'All season','urgency'=>'normal','location'=>'','collection_location'=>'','collection_notes'=>'','image_path'=>''];$requirements=[['id'=>'','category'=>'','size_label'=>'','quantity_needed'=>1,'condition_note'=>'']];
if($editing){$stmt=$pdo->prepare('SELECT * FROM clothing_requests WHERE id=? AND charity_id=?');$stmt->execute([$id,$charityId]);$request=$stmt->fetch();if(!$request){flash('error','That request does not belong to your organisation.');redirect('charity/requests.php');}$requirements=request_requirements($pdo,$id);}
if(is_post()){verify_csrf();$request=['title'=>trim($_POST['title']??''),'description'=>trim($_POST['description']??''),'season'=>$_POST['season']??'All season','urgency'=>$_POST['urgency']??'normal','location'=>trim($_POST['location']??''),'collection_location'=>trim($_POST['collection_location']??''),'collection_notes'=>trim($_POST['collection_notes']??''),'image_path'=>$request['image_path']??''];$ids=$_POST['requirement_id']??[];$cats=$_POST['category']??[];$sizes=$_POST['size_label']??[];$qtys=$_POST['quantity']??[];$notes=$_POST['condition_note']??[];$requirements=[];
 if(mb_strlen($request['title'])<4||mb_strlen($request['title'])>160)$errors[]='Use a clear request title between 4 and 160 characters.';if(mb_strlen($request['description'])<15||mb_strlen($request['description'])>3000)$errors[]='Describe the need in 15–3,000 characters.';if(!valid_enum($request['season'],['All season','Spring','Summer','Autumn','Winter']))$errors[]='Choose a valid season.';if(!valid_enum($request['urgency'],['low','normal','high','urgent']))$errors[]='Choose a valid urgency.';if(mb_strlen($request['location'])<2||mb_strlen($request['collection_location'])<2)$errors[]='Please give the city/area and collection location.';
 foreach($cats as $i=>$category){$category=trim($category);$size=trim($sizes[$i]??'');$quantity=filter_var($qtys[$i]??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>10000]]);if(!in_array($category,clothing_categories(),true)||!in_array($size,clothing_sizes(),true)||!$quantity){$errors[]='Every clothing requirement needs a category, size and quantity.';break;}$requirements[]=['id'=>filter_var($ids[$i]??'',FILTER_VALIDATE_INT)?:null,'category'=>$category,'size_label'=>$size,'quantity_needed'=>$quantity,'condition_note'=>trim($notes[$i]??'')];}
 if(!$requirements)$errors[]='Add at least one clothing requirement.';if(count($requirements)>8)$errors[]='A request can have up to eight requirements.';
 try{$uploaded=upload_request_image($_FILES['image']??[]);if($uploaded)$request['image_path']=$uploaded;}catch(RuntimeException $e){$errors[]=$e->getMessage();}
 if(!$errors){$pdo->beginTransaction();try{if($editing){$stmt=$pdo->prepare('UPDATE clothing_requests SET title=?,description=?,season=?,urgency=?,location=?,collection_location=?,collection_notes=?,image_path=? WHERE id=? AND charity_id=?');$stmt->execute([$request['title'],$request['description'],$request['season'],$request['urgency'],$request['location'],$request['collection_location'],$request['collection_notes']?:null,$request['image_path']?:null,$id,$charityId]);}else{$stmt=$pdo->prepare("INSERT INTO clothing_requests (charity_id,title,description,season,urgency,location,collection_location,collection_notes,image_path,status) VALUES (?,?,?,?,?,?,?,?,?,'active')");$stmt->execute([$charityId,$request['title'],$request['description'],$request['season'],$request['urgency'],$request['location'],$request['collection_location'],$request['collection_notes']?:null,$request['image_path']?:null]);$id=(int)$pdo->lastInsertId();}
 $existingStmt=$pdo->prepare('SELECT id FROM request_requirements WHERE request_id=?');$existingStmt->execute([$id]);$existingIds=array_map('intval',array_column($existingStmt->fetchAll(),'id'));$submittedIds=[];$upsert=$pdo->prepare('UPDATE request_requirements SET category=?,size_label=?,quantity_needed=?,condition_note=? WHERE id=? AND request_id=?');$insert=$pdo->prepare('INSERT INTO request_requirements (request_id,category,size_label,quantity_needed,condition_note) VALUES (?,?,?,?,?)');foreach($requirements as $r){if($r['id']&&in_array($r['id'],$existingIds,true)){$upsert->execute([$r['category'],$r['size_label'],$r['quantity_needed'],$r['condition_note']?:null,$r['id'],$id]);$submittedIds[]=$r['id'];}else{$insert->execute([$id,$r['category'],$r['size_label'],$r['quantity_needed'],$r['condition_note']?:null]);}}
 foreach(array_diff($existingIds,$submittedIds) as $removed){$used=$pdo->prepare('SELECT COUNT(*) FROM donation_items WHERE request_requirement_id=?');$used->execute([$removed]);if((int)$used->fetchColumn()>0)throw new RuntimeException('A requirement with a pledge cannot be removed. Keep it or change its quantity.');$pdo->prepare('DELETE FROM request_requirements WHERE id=?')->execute([$removed]);}
 log_activity($pdo,$editing?'updated a clothing request':'posted a clothing request',(int)$user['id'],'request',$id);$pdo->commit();flash('success',$editing?'Your request was updated.':'Your request is live for donors to find.');redirect('charity/requests.php');}catch(Throwable $e){$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'We could not save the request. Please try again.';}}
}
$pageTitle=$editing?'Edit clothing request':'Post a clothing need';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell" style="max-width:960px"><div class="welcome-row"><div><span class="eyebrow">Specific asks get fulfilled</span><h1><?= $editing?'Edit a clothing request':'Post a clothing need'?></h1><p>Help donors give exactly the things your community can use.</p></div><a class="button button-outline" href="<?=e(url('charity/requests.php'))?>">Back to requests</a></div><div class="panel"><?php if($errors):?><div class="flash flash-error"><span><?=e(implode(' ',$errors))?></span></div><?php endif;?><form method="post" enctype="multipart/form-data" data-loading><?=csrf_field()?><input type="hidden" name="id" value="<?=e((string)$id)?>"><div class="form-grid"><div class="field field-full"><label for="title">Request title</label><input class="input" id="title" name="title" maxlength="160" required placeholder="e.g. Winter layers for families finding home" value="<?=e($request['title'])?>"></div><div class="field field-full"><label for="description">Why this clothing matters</label><textarea class="textarea" id="description" name="description" maxlength="3000" required><?=e($request['description'])?></textarea><p class="help">Be specific about who will receive the items and why now.</p></div><div class="field"><label for="season">Season</label><select class="select" id="season" name="season"><?php foreach(['All season','Spring','Summer','Autumn','Winter'] as $s):?><option value="<?=e($s)?>" <?= $request['season']===$s?'selected':'' ?>><?=e($s)?></option><?php endforeach;?></select></div><div class="field"><label for="urgency">Urgency</label><select class="select" id="urgency" name="urgency"><?php foreach(['low','normal','high','urgent'] as $s):?><option value="<?=e($s)?>" <?= $request['urgency']===$s?'selected':'' ?>><?=e(ucfirst($s))?></option><?php endforeach;?></select></div><div class="field"><label for="location">City or area</label><input class="input" id="location" name="location" maxlength="150" required value="<?=e($request['location'])?>"></div><div class="field"><label for="collection_location">Collection location</label><input class="input" id="collection_location" name="collection_location" maxlength="255" required placeholder="e.g. 21 Market Street, Leeds" value="<?=e($request['collection_location'])?>"></div><div class="field field-full"><label for="collection_notes">Drop-off notes <small>(optional)</small></label><input class="input" id="collection_notes" name="collection_notes" maxlength="1000" placeholder="Parking, entrance, or packaging guidance" value="<?=e($request['collection_notes'])?>"></div><div class="field field-full"><label for="image">Request image <small>(optional, JPG/PNG/WebP up to 3 MB)</small></label><input class="input" style="padding:8px" type="file" id="image" name="image" accept="image/jpeg,image/png,image/webp"></div></div><hr style="border:0;border-top:1px solid var(--line);margin:25px 0 18px"><div class="panel-heading"><div><h2>What do you need?</h2><p class="help">Split categories and sizes so donors can pledge accurately.</p></div><button class="button button-small button-outline" type="button" data-add-requirement>Add another +</button></div><div data-requirements><?php foreach($requirements as $r):?><div class="requirement-form-item"><input type="hidden" name="requirement_id[]" value="<?=e((string)($r['id']??''))?>"><div class="field"><label>Category</label><select class="select" name="category[]" required><option value="">Choose</option><?php foreach(clothing_categories() as $c):?><option value="<?=e($c)?>" <?=($r['category']??'')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="field"><label>Size</label><select class="select" name="size_label[]" required><option value="">Size</option><?php foreach(clothing_sizes() as $s):?><option value="<?=e($s)?>" <?=($r['size_label']??'')===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div><div class="field"><label>Quantity</label><input class="input" type="number" name="quantity[]" min="1" max="10000" required value="<?=e((string)($r['quantity_needed']??1))?>"></div><div class="field"><label>Condition / detail</label><input class="input" name="condition_note[]" maxlength="255" value="<?=e($r['condition_note']??'')?>" placeholder="e.g. Waterproof"></div><button type="button" class="button button-danger button-small remove-req">Remove</button></div><?php endforeach;?></div><div class="form-actions"><a class="button button-outline" href="<?=e(url('charity/requests.php'))?>">Cancel</a><button class="button" type="submit"><?= $editing?'Save request':'Publish request'?> →</button></div></form></div></div></section>
